const updateAgent = `-- name: UpdateAgent :exec
UPDATE
    agents
SET
    cwd = $1,
    flags = $2,
    prompt = $3,
    pane_id = $4,
    state = $5,
    session_id = CASE WHEN $6 != '' THEN
        $6
    ELSE
        session_id
    END,
    workflow_id = $7
WHERE
    id = $8
`

type UpdateAgentParams struct {
	Cwd        string
	Flags      string
	Prompt     string
	PaneID     string
	State      string
	SessionID  interface{}
	WorkflowID string
	ID         string
}

func (q *Queries) UpdateAgent(ctx context.Context, arg UpdateAgentParams) error {
	_, err := q.db.Exec(ctx, updateAgent,
		arg.Cwd,
		arg.Flags,
		arg.Prompt,
		arg.PaneID,
		arg.State,
		arg.SessionID,
		arg.WorkflowID,
		arg.ID,
	)
	return err
}

const upsertTranscript = `-- name: UpsertTranscript :exec
INSERT INTO agent_transcripts(
    agent_id,
    content,
    synced_offset,
    synced_at)
VALUES (
    $1,
    $2,
    $3,
    NOW())
ON CONFLICT (
    agent_id)
    DO UPDATE SET
        content = excluded.content,
        synced_offset = excluded.synced_offset,
        synced_at = NOW()
`

type UpsertTranscriptParams struct {
	AgentID      string
	Content      string
	SyncedOffset int64
}

func (q *Queries) UpsertTranscript(ctx context.Context, arg UpsertTranscriptParams) error {
	_, err := q.db.Exec(ctx, upsertTranscript, arg.AgentID, arg.Content, arg.SyncedOffset)
	return err
}
